const { chromium } = require('playwright');
const path = require('path');
const outDir = path.join(process.cwd(), 'web/usability');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  });

  // Fixture
  {
    const page = await browser.newPage({ viewport: { width: 1100, height: 900 } });
    await page.goto('file://' + path.join(outDir, 'eps-delta-glosses.html'), { waitUntil: 'networkidle' });
    await page.screenshot({ path: path.join(outDir, 'eps-delta-glosses.png'), fullPage: true });
    await page.close();
    console.log('fixture ok');
  }

  async function captureStart(width, height, outName) {
    const page = await browser.newPage({ viewport: { width, height } });
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.setItem('simplify-viewer-playback-tour-v1', '1');
    });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    if (await page.locator('#uiTourSkip').isVisible({ timeout: 1500 }).catch(() => false)) {
      await page.locator('#uiTourSkip').click();
    }
    await page.waitForTimeout(400);
    const metrics = await page.evaluate(() => {
      const eps = document.querySelector('label[for], label:has(#epsilonInput)') || document.querySelector('#epsilonInput')?.closest('label');
      const delta = document.querySelector('#deltaInput')?.closest('label');
      const form = document.querySelector('.upload-form');
      const header = document.querySelector('header');
      return {
        epsText: eps ? eps.innerText.replace(/\s+/g, ' ').trim() : null,
        deltaText: delta ? delta.innerText.replace(/\s+/g, ' ').trim() : null,
        dropHint: (document.querySelector('.dropHint-sub')?.innerText || '').replace(/\s+/g, ' ').slice(0, 160),
        mobileHelp: (document.querySelector('.mobile-start-help')?.innerText || '').replace(/\s+/g, ' ').slice(0, 160),
        headerH: header?.getBoundingClientRect().height,
        formH: form?.getBoundingClientRect().height,
        scrollWidth: document.documentElement.scrollWidth,
        clientWidth: document.documentElement.clientWidth,
        loadTop: document.getElementById('loadBtn')?.getBoundingClientRect().top,
        epsTop: document.getElementById('epsilonInput')?.getBoundingClientRect().top,
      };
    });
    await page.screenshot({ path: path.join(outDir, outName), fullPage: false });
    await page.close();
    return metrics;
  }

  async function captureLoaded(width, height, outName) {
    const page = await browser.newPage({ viewport: { width, height } });
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.setItem('simplify-viewer-playback-tour-v1', '1');
    });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    if (await page.locator('#uiTourSkip').isVisible({ timeout: 1500 }).catch(() => false)) {
      await page.locator('#uiTourSkip').click();
    }
    const isMobile = width <= 720;
    if (isMobile) {
      await page.click('#preloadedTrigger');
      await page.waitForTimeout(200);
      const opt = await page.$('[data-value="1"], .trace-picker-list button, .trace-picker-list li, #tracePickerList button');
      if (opt) await opt.click();
      else await page.selectOption('#traceSelect', '1');
    } else {
      await page.selectOption('#traceSelect', '1');
    }
    await page.click('#loadBtn');
    await page.waitForFunction(
      () => document.body.classList.contains('playback-ready') || (document.querySelector('#uploadStatus')?.textContent || '').includes('Loaded'),
      { timeout: 180000 }
    );
    await page.waitForTimeout(800);
    if (isMobile) {
      // open controls panel if needed
      const openBtn = page.locator('#mobilePanelOpen');
      if (await openBtn.isVisible().catch(() => false)) await openBtn.click();
      await page.waitForTimeout(300);
    }
    const metrics = await page.evaluate(() => {
      const streamLabel = document.querySelector('label[for="toggle-stream"], label:has(#toggle-stream)')?.innerText || '';
      return {
        paramsText: (document.getElementById('paramsBar')?.innerText || '').replace(/\s+/g, ' ').slice(0, 180),
        statusGrid: (document.getElementById('statusGrid')?.innerText || '').replace(/\s+/g, ' ').trim(),
        streamLabel: streamLabel.replace(/\s+/g, ' ').trim(),
        scrollWidth: document.documentElement.scrollWidth,
        clientWidth: document.documentElement.clientWidth,
        headerH: document.querySelector('header')?.getBoundingClientRect().height,
      };
    });
    await page.screenshot({ path: path.join(outDir, outName), fullPage: false });
    await page.close();
    return metrics;
  }

  const start1280 = await captureStart(1280, 800, 'eps-delta-glosses-1280-live.png');
  console.log('start1280', JSON.stringify(start1280));
  const start900 = await captureStart(900, 800, 'eps-delta-glosses-900-live.png');
  console.log('start900', JSON.stringify(start900));
  const start721 = await captureStart(721, 800, 'eps-delta-glosses-721-live.png');
  console.log('start721', JSON.stringify(start721));
  const start390 = await captureStart(390, 844, 'eps-delta-glosses-390-live.png');
  console.log('start390', JSON.stringify(start390));

  const loaded1280 = await captureLoaded(1280, 800, 'eps-delta-glosses-1280-loaded-live.png');
  console.log('loaded1280', JSON.stringify(loaded1280));
  const loaded390 = await captureLoaded(390, 844, 'eps-delta-glosses-390-loaded-live.png');
  console.log('loaded390', JSON.stringify(loaded390));

  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
