const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  });
  for (const width of [1280, 900, 820, 721]) {
    const page = await browser.newPage({ viewport: { width, height: 800 } });
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.setItem('simplify-viewer-playback-tour-v1', '1');
    });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    if (await page.locator('#uiTourSkip').isVisible({ timeout: 1000 }).catch(() => false)) {
      await page.locator('#uiTourSkip').click();
    }
    // Measure with glosses, then hide glosses via CSS and remeasure
    const withGloss = await page.evaluate(() => {
      const r = (sel) => {
        const el = document.querySelector(sel);
        if (!el) return null;
        const b = el.getBoundingClientRect();
        return { top: Math.round(b.top), left: Math.round(b.left), w: Math.round(b.width), h: Math.round(b.height) };
      };
      return {
        headerH: Math.round(document.querySelector('header').getBoundingClientRect().height),
        eps: r('#epsilonInput'),
        delta: r('#deltaInput'),
        load: r('#loadBtn'),
        compare: r('.header-baseline'),
        formW: Math.round(document.querySelector('.upload-form').getBoundingClientRect().width),
        glossW: [...document.querySelectorAll('.param-gloss')].map(g => Math.round(g.getBoundingClientRect().width)),
      };
    });
    await page.addStyleTag({ content: '.upload-form .param-gloss { display: none !important; }' });
    await page.waitForTimeout(50);
    const withoutGloss = await page.evaluate(() => {
      const r = (sel) => {
        const el = document.querySelector(sel);
        if (!el) return null;
        const b = el.getBoundingClientRect();
        return { top: Math.round(b.top), left: Math.round(b.left), w: Math.round(b.width), h: Math.round(b.height) };
      };
      return {
        headerH: Math.round(document.querySelector('header').getBoundingClientRect().height),
        eps: r('#epsilonInput'),
        delta: r('#deltaInput'),
        load: r('#loadBtn'),
        compare: r('.header-baseline'),
      };
    });
    console.log(width, 'WITH', JSON.stringify(withGloss));
    console.log(width, 'WITHOUT', JSON.stringify(withoutGloss));
    await page.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
